function generateSerial(max) {
  if (!max) {
    max = 1000;
  }
  return Math.floor(Math.random() * max);
}
console.log(generateSerial()); // Retorna serial entre 0 e 1000

function generateSerial(max) {
  max = max || 1000; // Curto-circuito!
  return Math.floor(Math.random() * max);
}
console.log(generateSerial(100)); // 0 a 100
console.log(generateSerial());    // 0 a 1000 (default)

function generateSerial(max) {
  max = max ?? 1000; // Só aplica default se for null ou undefined!
  return Math.floor(Math.random() * max);
}
console.log(generateSerial(0)); // Retorna 0 (respeita o valor zero!)

