// ============================================================================
// Aula 9.1: Operadores Booleanos - Rodrigo Branas
// ============================================================================

console.info('1. IGUALDADE AMPLA (==) VS ESTRITA (===)');
console.log('5 == "5":', 5 == "5");         // true (converte string para number)
console.log('5 === "5":', 5 === "5");       // false (tipos diferentes!)
console.log('0 == "":', 0 == "");           // true (coerção oculta)
console.log('0 === "":', 0 === "");         // false
console.log('null == undefined:', null == undefined);   // true
console.log('null === undefined:', null === undefined); // false

console.info('\n2. OPERADORES LÓGICOS E CURTO-CIRCUITO');
// AND (&&): retorna o primeiro falsy ou o último operando
console.log('1 && 2:', 1 && 2);             // 2
console.log('0 && 2:', 0 && 2);             // 0
console.log('"user" && "autenticado":', "user" && "autenticado"); // "autenticado"

// OR (||): retorna o primeiro truthy ou o último operando
console.log('0 || 2:', 0 || 2);             // 2
console.log('1 || 0:', 1 || 0);             // 1
console.log('"" || "visitante":', "" || "visitante"); // "visitante"

console.info('\n3. ESTUDO DE CASO: generateSerial(max)');
function generateSerial(max) {
  max = max || 1000;
  return Math.floor(Math.random() * max);
}
console.log('generateSerial(100):', generateSerial(100));
console.log('generateSerial():', generateSerial()); // assume 1000

// Comparação com Coalescência Nula (??):
const estoque = 0;
console.log('estoque || 10:', estoque || 10); // 10 (inesperado! 0 virou falsy)
console.log('estoque ?? 10:', estoque ?? 10); // 0 (correto! preserva o zero)

console.info('\n4. OPERADOR TERNÁRIO');
const idade = 20;
const podeDirigir = idade >= 18 ? 'Habilitado' : 'Não habilitado';
console.log('Status para idade 20:', podeDirigir);
console.log('(10 >= 18) ? "good" : "bad":', (10 >= 18) ? 'good' : 'bad');
console.log('(0) ? "good" : "bad":', (0) ? 'good' : 'bad');
